sqlMap.update:
UPDATE PA_PARAM_DATA SET END_MONTH = CASE WHEN END_MONTH < TO_CHAR(TO_DATE((substr(#START_MONTH:VARCHAR#,1,4)||'-'||substr(#START_MONTH:VARCHAR#,5,6)||'-01'),'YYYY-MM-DD')-1,'YYYYMM') THEN END_MONTH ELSE TO_CHAR(TO_DATE((substr(#START_MONTH:VARCHAR#,1,4)||'-'||substr(#START_MONTH:VARCHAR#,5,6)||'-01'),'YYYY-MM-DD')-1,'YYYYMM') END, UPDATE_DATE = SYSDATE, UPDATED_BY = #UPDATED_BY:VARCHAR# WHERE ROWID IN (SELECT ROWID FROM (SELECT ROWID, ROW_NUMBER() OVER(ORDER BY START_MONTH DESC) RN FROM PA_PARAM_DATA WHERE PARAM_NO = #PARAM_NO:NUMERIC# AND PERSON_ID = #PERSON_ID:VARCHAR#
PARAM_DATA_NO <> #NOT_PARAM_DATA_NO:VARCHAR#
) WHERE RN = 1)
